window.addEventListener("scroll", function () {
var header = document.querySelector(".header-top");
header.classList.toggle("box-shadow-white", window.scrollY > 120);
if (window.innerWidth >= 500) {
header.classList.toggle("bg-transparent", window.scrollY <= 120);
header.classList.toggle("bg-darkgray-2", window.scrollY > 120);
// header.classList.toggle("py-2", window.scrollY > 120);
}
});
window.onload = function () {
window.onscroll();
};
window.onscroll = function () {
scrollFunction();
};
function scrollFunction() {
if (document.body.scrollTop > 20 || document.documentElement.scrollTop > 20) {
document.getElementById("goToTopBtn").style.display = "block";
} else {
document.getElementById("goToTopBtn").style.display = "none";
}
}
function goToTop() {
document.body.scrollTop = 0;
document.documentElement.scrollTop = 0;
}
const pageContentNavigationClick = (targetId) => {
const element = document.getElementById(targetId);
element.scrollIntoView({
behavior: "smooth",
block: "nearest",
inline: "start",
});
};
const scrollToSection = (targetId) => {
document.getElementById(targetId).scrollIntoView({
behavior: "smooth",
block: "start",
});
};
const openAboutTab = (tabButtonId) => {
new bootstrap.Tab(document.getElementById(tabButtonId)).show();
scrollToSection("about-me");
};
// Close the mobile menu after a header link is clicked
document.querySelectorAll(".header-top .navbar-collapse .nav-link").forEach((link) => {
link.addEventListener("click", () => {
const menu = document.querySelector(".header-top .navbar-collapse.show");
if (menu === null || typeof bootstrap === "undefined") {
return;
}
const collapse = bootstrap.Collapse.getInstance(menu) || new bootstrap.Collapse(menu, { toggle: false });
collapse.hide();
});
});
// Footer copyright year
document.querySelectorAll(".current-year").forEach((element) => {
element.textContent = new Date().getFullYear();
});
// Footer: copy the email address
document.querySelectorAll(".contact-copy").forEach((button) => {
button.addEventListener("click", () => {
const original = button.innerHTML;
navigator.clipboard
.writeText(button.dataset.copy)
.then(() => {
button.innerHTML = '<i class="fa-solid fa-check"></i><span>Copied</span>';
setTimeout(() => {
button.innerHTML = original;
}, 1600);
})
.catch(() => {
window.location.href = "mailto:" + button.dataset.copy;
});
});
});